import{_ as o,o as r,c as a,ag as l}from"./chunks/framework.DzGOF12C.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"기능주의란 — 마음상태 = 기능적 상태","slug":"기능주의란-—-마음상태-기능적-상태","link":"#기능주의란-—-마음상태-기능적-상태","children":[]},{"level":2,"title":"순환성을 피하는 두 가지 방법","slug":"순환성을-피하는-두-가지-방법","link":"#순환성을-피하는-두-가지-방법","children":[{"level":3,"title":"튜링기계에 의한 설명 (퍼트남)","slug":"튜링기계에-의한-설명-퍼트남","link":"#튜링기계에-의한-설명-퍼트남","children":[]},{"level":3,"title":"램지-루이스(Ramsey-Lewis) 방법","slug":"램지-루이스-ramsey-lewis-방법","link":"#램지-루이스-ramsey-lewis-방법","children":[]}]},{"level":2,"title":"분석적 기능주의와 심리학적 기능주의","slug":"분석적-기능주의와-심리학적-기능주의","link":"#분석적-기능주의와-심리학적-기능주의","children":[]},{"level":2,"title":"기능주의는 \\"꿈의 이론\\"인가","slug":"기능주의는-꿈의-이론-인가","link":"#기능주의는-꿈의-이론-인가","children":[]},{"level":2,"title":"문제 1 — 감각질(Qualia)","slug":"문제-1-—-감각질-qualia","link":"#문제-1-—-감각질-qualia","children":[]},{"level":2,"title":"문제 2 — 기능주의는 동일론인가, 이원론인가 (김재권의 딜레마)","slug":"문제-2-—-기능주의는-동일론인가-이원론인가-김재권의-딜레마","link":"#문제-2-—-기능주의는-동일론인가-이원론인가-김재권의-딜레마","children":[]}],"relativePath":"philosophy/Philosophy-of-Mind/05. 기능주의.md","filePath":"philosophy/Philosophy-of-Mind/05. 기능주의.md"}'),e={name:"philosophy/Philosophy-of-Mind/05. 기능주의.md"};function n(i,t,s,u,d,h){return r(),a("div",null,[...t[0]||(t[0]=[l('<h2 id="기능주의란-—-마음상태-기능적-상태" tabindex="-1">기능주의란 — 마음상태 = 기능적 상태 <a class="header-anchor" href="#기능주의란-—-마음상태-기능적-상태" aria-label="Permalink to &quot;기능주의란 — 마음상태 = 기능적 상태&quot;">​</a></h2><p>심신동일론이 &quot;마음 상태 = 두뇌 상태&quot;를 주장했다면, <strong>기능주의(functionalism)</strong>는 &quot;마음 상태 = <strong>기능적 상태</strong>&quot;를 주장한다. 기능적 개념은 일상에도 흔하다 — 무엇을 <strong>카뷰레터</strong>로 만드는 것은 그것이 석유와 공기를 혼합해 엔진에 전달하는 <strong>역할</strong>을 수행한다는 사실이지, 무엇으로 만들어졌는지가 아니다. 항생제도 마찬가지로 병원균을 죽이는 역할로 정의된다.</p><p>기능주의는 마음 상태를 <strong>입력과 출력을 매개하는 인과적 역할</strong>로 정의한다 — 입출력으로 정의 가능하다고 본다는 점에서 행동주의의 아이디어를 물려받지만, 그 입출력 사이에 <strong>다른 마음 상태</strong>가 개입하는 것을 허용한다는 점이 행동주의와의 결정적 차이다(믿음-욕구의 상호의존 문제를 정면으로 받아들이는 셈). 물론 그렇다면 순환성의 우려가 다시 제기되는데, 이는 뒤에서 다룰 튜링기계·램지-루이스 방법으로 해소를 시도한다.</p><p>기능주의는 두 가지 중요한 함축을 갖는다.</p><ul><li><strong>복수실현가능성(multiple realizability)</strong>: 기능주의의 &quot;트레이드마크&quot;라 할 아이디어로, 하나의 마음 상태가 여러 다른 물리적 재료로 &quot;실현&quot;될 수 있다는 것 — 사람의 고통, 문어의 고통, 화성인의 고통, 로봇의 고통은 서로 완전히 다른 물리적 재료로 실현되지만 같은 <strong>기능</strong>을 수행한다는 공통점을 가진다.</li><li><strong>심리과학의 자율성(autonomy)</strong>: 복수실현가능성으로부터, 두뇌를 연구하는 것은 마음 상태의 한 가지 실현을 연구하는 것일 뿐 마음 상태 자체에 대한 연구와 같지 않다는 결론이 따라 나온다. 인지과학은 이 발상 위에서 발달한 독자적 과학이다.</li></ul><h2 id="순환성을-피하는-두-가지-방법" tabindex="-1">순환성을 피하는 두 가지 방법 <a class="header-anchor" href="#순환성을-피하는-두-가지-방법" aria-label="Permalink to &quot;순환성을 피하는 두 가지 방법&quot;">​</a></h2><h3 id="튜링기계에-의한-설명-퍼트남" tabindex="-1">튜링기계에 의한 설명 (퍼트남) <a class="header-anchor" href="#튜링기계에-의한-설명-퍼트남" aria-label="Permalink to &quot;튜링기계에 의한 설명 (퍼트남)&quot;">​</a></h3><p><strong>퍼트남(Hilary Putnam)</strong>은 튜링기계(Turing machine) 개념을 빌려 온다. 1000원을 넣으면 콜라가 나오는 자판기의 작동은 다음과 같은 <strong>기계표(machine table)</strong>로 완전히 포착된다 — 상태 S1에서 500원이 들어오면 상태 S2로, S2에서 500원이 더 들어오면 콜라를 내주고 S1로 돌아가는 식이다. 여기서 기계 상태 S1, S2는 이 표에 의해(암묵적으로) 완전히 정의되며, 이 기계는 전자·기계·생물학적 재료 등 다양한 방식으로 실현될 수 있지만 S1, S2라는 상태 자체가 그 중 어느 하나의 실현과 동일한 것은 아니다.</p><p>퍼트남의 <strong>기능적 상태 가설</strong>은 다음 네 명제로 구성된다.</p><ol><li>고통을 느낄 수 있는 모든 유기체는 확률적 기계(probabilistic automaton)다.</li><li>고통을 느낄 수 있는 모든 유기체는 적절한 기능적 구조(&quot;기술&quot;)를 적어도 하나 갖는다 — 고통을 느낄 수 있다는 것은 그런 기능적 구조를 가진다는 것과 다름없다.</li><li>그런 유기체는 그 기술을 가진 부분들로 분해될 수 없다.</li><li>그 기술을 가진 유기체는 특정 감각 입력의 부분집합을 가질 때 오직 그 경우에만 고통을 갖는다.</li></ol><p><strong>두뇌상태 가설(동일론) vs. 기능상태 가설</strong>: 동일론은 &quot;X가 고통을 가진다 ⇔ X가 적절한 물리-화학적 구조의 두뇌를 가지고, 물리-화학적 상태 P에 있다&quot;고 주장한다 — 즉 고통을 가진 모든 존재가 공유하는 하나의 두뇌 상태가 있다는 것인데, 퍼트남은 이 개연성이 낮다고 본다. 반면 &quot;두 시스템이 유사한 행동을 보인다는 것은 그 두 시스템이 <strong>기능적 구조</strong>에서 유사하다고 볼 이유가 되지만, 행동의 유사성은 물리적 세부사항의 유사성에 대해서는 훨씬 약한 이유밖에 되지 못한다.&quot; 종-독립적인 신경생리학 법칙보다는 종-독립적인 (기능적) 심리학 법칙을 기대하는 쪽이 더 합당하다는 것이다.</p><h3 id="램지-루이스-ramsey-lewis-방법" tabindex="-1">램지-루이스(Ramsey-Lewis) 방법 <a class="header-anchor" href="#램지-루이스-ramsey-lewis-방법" aria-label="Permalink to &quot;램지-루이스(Ramsey-Lewis) 방법&quot;">​</a></h3><p>기능주의는 마음 상태를 입출력 패턴에 의해 <strong>암묵적으로</strong> 정의하는데, 이를 <strong>명시적</strong> 정의로 바꾸는 기법이 램지-루이스 방법이다. 예컨대 다음 세 원리로 이루어진 (단순화한) &quot;이론&quot; T가 있다고 하자.</p><blockquote><p>고통은 신체적 상해에 의해 야기된다. 고통은 불안을 야기하고 소리를 지르게 한다. 불안은 얼굴을 찌푸리게 만든다.</p></blockquote><p>여기서 &quot;고통&quot;, &quot;불안&quot;은 아직 정의되지 않은 이론적 용어이고 나머지는 이미 이해된 입출력 표현이다. 이 원리들의 연언을 T(고통, 불안)으로 쓰고, 이론적 용어를 변항으로 바꾸어 T(M1, M2)로, 여기에 존재양화사를 붙여 <strong>램지 문장(Ramsey sentence)</strong> ∃M1∃M2 T(M1, M2)를 만든다. 이제 마음 상태 개념을 다음처럼 명시적으로 정의할 수 있다.</p><blockquote><p>x가 고통 상태에 있다 =def ∃M1∃M2 [T(M1, M2) &amp; x는 M1에 있다]</p></blockquote><p>이렇게 하면 이론에 속한 이론적 용어들을 그 이론 전체에 의해 <strong>전체적으로(holistically)</strong>, 순환 없이 정의할 수 있다. 다만 이 방법에도 문제가 있다.</p><ul><li>이론 T의 일반 원리 중 하나라도 거짓이면 T 전체가 거짓이 되고, 램지 문장도 거짓이 되어 정의 자체가 공허해질(아무것도 만족시키지 못할) 위험이 있다.</li><li>두 사람이 고통에 대해 서로 다른 이론을 가진다면, 두 사람이 쓰는 &quot;고통&quot;의 의미 자체가 달라진다는 귀결이 따라 나온다 — 그렇다면 고통에 대한 실질적인 이견(논쟁)이 애초에 불가능해지는 것 아닌가?</li></ul><h2 id="분석적-기능주의와-심리학적-기능주의" tabindex="-1">분석적 기능주의와 심리학적 기능주의 <a class="header-anchor" href="#분석적-기능주의와-심리학적-기능주의" aria-label="Permalink to &quot;분석적 기능주의와 심리학적 기능주의&quot;">​</a></h2><p>마음 상태를 정의하는 이론 T가 무엇이냐에 따라 기능주의는 다시 나뉜다.</p><table tabindex="0"><thead><tr><th></th><th>정의에 쓰이는 이론</th></tr></thead><tbody><tr><td><strong>분석적 기능주의(analytical functionalism)</strong></td><td>상식심리학(통속심리학, folk psychology)에 국한</td></tr><tr><td><strong>심리학적 기능주의(psycho-functionalism)</strong></td><td>발전된 과학적 심리학</td></tr></tbody></table><p><strong>통속심리학</strong>이란 일상적으로 사람들의 행동을 예측·설명하는 데 쓰는 원리들의 집합이다(예: &quot;고통 속에 있는 사람은 그것을 완화하려는 경향이 있다&quot;, &quot;P를 원하고 Q가 P를 확보해 준다고 믿는 사람은 Q를 하려 할 것이다&quot;). 이는 문법 지식처럼 암묵적으로 소유하는 지식으로 여겨지며, 분석적 기능주의자들은 이 원리들이 심리적 개념을 암묵적으로 정의한다고 본다.</p><p><strong>김재권(Jaegwon Kim)</strong>은 통속심리학이 보편적이고 안정적이라는 점에서 분석적 기능주의를 선호할 이유가 있다고 본다 — 욕구와 믿음이 결합해 행동을 낳는다는 원리는 고대 그리스인이나 중국인의 이야기 속 인물의 행위도 우리가 이해·공감할 수 있게 해주는 원리라는 것. 다만 김재권은 통속심리학과 과학적 심리학이 경쟁 관계가 아니라, 서로 다른 <strong>추상화 수준</strong>의 이론으로서 양립 가능하다고 본다 — 통속심리학은 일상적 심리 개념을 기능적으로 정의하는 토대로, 과학적 심리학은 과학적 개념을 정의하는 데 각각 적합하다는 것.</p><h2 id="기능주의는-꿈의-이론-인가" tabindex="-1">기능주의는 &quot;꿈의 이론&quot;인가 <a class="header-anchor" href="#기능주의는-꿈의-이론-인가" aria-label="Permalink to &quot;기능주의는 &quot;꿈의 이론&quot;인가&quot;">​</a></h2><p>기능주의는 20세기 분석철학의 주요 이론적 성과 중 하나로 꼽히며, 다음 네 장점을 동시에 갖출 수 있다고 여겨져 왔다 — (1) 실재론적 견해, (2) 물리주의에 친화적, (3) 마음의 인과력 인정, (4) 심리학·인지과학의 자율성(특히 뇌과학으로부터의 독립성) 확보. 그러나 이 강점들 각각에 심각한 반론이 따라붙는다.</p><h2 id="문제-1-—-감각질-qualia" tabindex="-1">문제 1 — 감각질(Qualia) <a class="header-anchor" href="#문제-1-—-감각질-qualia" aria-label="Permalink to &quot;문제 1 — 감각질(Qualia)&quot;">​</a></h2><p>경험에는 &quot;잘 익은 토마토를 보는 것&quot;과 &quot;시금치를 보는 것&quot;을 명백히 가르는 독특한 질적 특성이 있다 — 이를 <strong>감각질(qualia)</strong>이라 부른다. 문제는 감각질이 그 <strong>인과적 역할</strong>만으로는 완전히 포착되지 않는 것 같다는 점이다 — 인과적 역할과 현상적 성질이 따로 분리될 수 있다는 것이 <strong>전도된 감각질(inverted qualia)</strong> 사고실험으로 뒷받침되는 듯 보인다.</p><p>색상환을 180도 회전시켜 얻은 색채 경험을 생각해 보자. 두 사람이 정확히 같은 기능적 상태에 있으면서도(같은 자극에 같은 반응을 보이면서도) 서로 다른 색채 경험(마음 상태)을 하고 있다면, 기능주의는 이 차이를 놓치는 것 아닌가?</p><p>기능주의를 옹호하려면 두 사람 사이에 실은 어떤 기능적·행동적 차이가 있음을 보여야 하는데, 몇 가지 시도가 있다 — ①색에 대한 정서적 반응(가령 파랑 계열이 더 &quot;차갑게&quot; 느껴지는 것)의 차이, ②정상인은 빨강-노랑 사이보다 파랑-빨강 사이에서 색을 더 잘 구분하므로 색상환 회전은 구분 가능한 색 수의 차이를 낳을 수 있다는 것, ③채도·명도 차원까지 고려하면(정상적으로는 노랑의 최대 채도가 파랑·빨강보다 높은 명도에서 나타나는데, 감각질이 전도된 사람은 이 관계가 뒤바뀌므로) 행동 차이가 예측된다는 것. 다만 이런 반론들이 실제로 효력이 있는지는 여전히 논란거리다. (참고로 이 문제가 기능주의에만 발생하는지, 동일론에도 발생하는지는 별도로 따져볼 문제다.)</p><p><strong>결여된 감각질(absent qualia)</strong> 문제도 관련이 있다 — 마음 상태에 결부된 기능을 완벽히 수행하면서도 감각질 자체는 전혀 없는 시스템(예: 로봇)이 가능하지 않은가? 네드 블락(Ned Block)의 <strong>&quot;중국 두뇌(China brain)&quot;</strong> 사고실험이 이를 예리하게 보여준다 — 10억 명의 중국인이 각자 뉴런 역할을 하며 무전기로 연결되어 뇌 신경망과 동일한 기능적 구조를 구현한다고 하자. 기능적으로는 완벽히 동일한 상태를 재현하더라도, 과연 이 &quot;중국(전체)&quot;이 감각질을 가진다고 할 수 있을까?</p><h2 id="문제-2-—-기능주의는-동일론인가-이원론인가-김재권의-딜레마" tabindex="-1">문제 2 — 기능주의는 동일론인가, 이원론인가 (김재권의 딜레마) <a class="header-anchor" href="#문제-2-—-기능주의는-동일론인가-이원론인가-김재권의-딜레마" aria-label="Permalink to &quot;문제 2 — 기능주의는 동일론인가, 이원론인가 (김재권의 딜레마)&quot;">​</a></h2><p>기능주의의 핵심 주장은 두 갈래다.</p><ul><li>(A) 정신적 속성은 기능적 역할로 정의되며, 이질적인 물리적 속성에 의해 실현될 뿐 어떤 특정 물리적 속성과도 동일하지 않다.</li><li>(B) 그럼에도 정신적 속성은 과학적으로 적합한 속성이며 심리학·인지과학의 연구 대상이다 — 물리적 속성으로 환원되지 않는다는 점에서 심리학은 <strong>자율적</strong>이다.</li></ul><p><strong>김재권</strong>은 (A)와 (B) 사이에 긴장이 있다고 주장하며 두 논증을 제시한다.</p><p><strong>논증 1 — 선언적 속성 논증</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>(1)</td><td>정신적 속성 M = &quot;인과적 역할 H를 가진 어떤 속성을 가짐&quot;의 속성 (이차 속성으로 해석)</td></tr><tr><td>(2)</td><td>사람에서는 Q1, 문어에서는 Q2, 화성인에서는 Q3가 M을 실현하며, Q1·Q2·Q3는 물리적으로 서로 이질적(heterogeneous)이다</td></tr><tr><td>(3)</td><td>따라서 M = Q1 ∨ Q2 ∨ Q3 (이질적인 <strong>선언적(disjunctive) 속성</strong>)</td></tr><tr><td>(4)</td><td>이질적 선언적 속성은 과학적 속성으로 부적합하다 (예: &quot;쥐덫&quot;, &quot;반려동물&quot;에 대한 유용한 일반 법칙은 기대하기 어렵다)</td></tr><tr><td>(5)</td><td>따라서 M은 과학적 속성으로 부적합하다</td></tr></tbody></table><p>심리학의 자율성을 옹호하는 기능주의자들은 (3)을 거부한다 — 정신적 속성은 물리적 속성들에 의해 &quot;실현&quot;되지만, 그 실현자들의 단순한 선언을 넘어서는 무언가라는 것.</p><p><strong>논증 2 — 인과력 논증</strong> (선언 논제 (3)에 기대지 않고도 같은 결론에 도달)</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>(1)</td><td>M의 특정 사례가 가진 인과력은 그 물리적 실현자의 인과력에 다름없다 (특정 항생제의 인과력은 페니실린의 인과력에서 나온다 — 파피노의 인과논증 참고)</td></tr><tr><td>(2)</td><td>Q1, Q2, Q3은 이질적 속성이므로 인과력도 서로 다르다</td></tr><tr><td>(3)</td><td>과학적 속성은 인과력에 의해 개별화(individuate)된다 — 인과력이 같으면 같은 속성, 다르면 다른 속성</td></tr><tr><td>(4)</td><td>따라서 M은 과학적 속성이 아니다</td></tr></tbody></table><p>김재권의 결론: &quot;심적인 것의 복수실현가능성과 기능주의가 결합되면 심리학은 과학으로서의 통일성과 완전성을 상실할 위험에 처한다&quot; — 심적 종류는 물리적으로 다양한 실현자들로 산산이 부서지고, 과학적 속성에 요구되는 인과적·법칙적 통일성을 잃는다는 것.</p><p><strong>함축 — 종에 국한된 심리학</strong>: 이 논증이 옳다면, 인간의 고통·문어의 고통·화성인의 고통은 피상적으로만 유사할 뿐 엄밀히는 서로 다른 속성이다. 종에 제한되지 않는 단일한 &quot;심리학&quot;이란 없고, 인간 심리학·문어 심리학·화성인 심리학이 각각 있을 뿐이며, 각 종에 국한된 심리학조차 결국 물리적 속성으로 환원 가능한 속성을 다룬다는 점에서 그다지 자율적이지도 않다(참고: 이는 암스트롱의 인과이론과도 통하는 결론).</p><p>김재권의 이 논증이 건전한지는 여전히 뜨거운 논쟁거리다. 심리학의 자율성을 옹호하는 철학자들(포더, 블락 등)은 기능적 속성이 과학적으로 적합함이 이미 실제 과학(심리학·인지과학의 성공)에 의해 보여졌다는 근거로 반박을 시도한다.</p>',42)])])}const q=o(e,[["render",n]]);export{p as __pageData,q as default};
